    internal class eu07_contactors
    {
        // Seconds a position. The real contactors are electro-pneumatic, one valve each,
        // and follow the wheel as fast as it is turned; this is only so that a wheel spun
        // from 0 to 43 is heard as a run of contactors and not as one bang.
        public const float step_time = 0.05f;

        public readonly camshaft_contactor_set _series_set, _parallel_set, _field_set, _reverser_set;
        public readonly camshaft_contactor_set _isolators_12, _isolators_34;

        private readonly Fuse _control_power, _control_air;

        private int   _position = 0, _wanted = 0, _field = 0, _field_wanted = 0;
        private float _waited = 0.0f;

        public int position => _position;          // where the contactors ARE, not where the wheel is
        public int wanted   => _wanted;            // where the wheel is
        public int field    => _field;
        public int direction => _reverser_set.current_notch == 2 ? 1 : _reverser_set.current_notch == 3 ? -1 : 0;

        public eu07_contactors(Dictionary<string, circuit.branch_user> contactor_locations, Fuse control_power,
            Fuse control_air, Action<bool>? contactor_sound)
        {
            _control_power = control_power;
            _control_air   = control_air;

            // No camshaft_motor anywhere in here. The EU07 has no camshaft, and his motor
            // moves on its own timer; these are stepped from the simulation tick instead,
            // which also lets the whole thing run on a bench outside the game.
            //
            // The parallel set FIRST: a set applies its first row when it is made, and the
            // parallel set's first row is position 28, the bridge. The series set, made
            // after it, applies position 0 and leaves every contactor open.
            _parallel_set = new camshaft_contactor_set(_parallel_toggles, contactor_locations, null, contactor_sound);
            _series_set   = new camshaft_contactor_set(_series_toggles  , contactor_locations, null, contactor_sound);
            _field_set    = new camshaft_contactor_set(_field_toggles   , contactor_locations, null, contactor_sound);
            _reverser_set = new camshaft_contactor_set(_reverser_toggles, contactor_locations, null, null);

            // odlaczniki silnikow: row 1 normal (OS1, OS3 closed), row 2 the pair cut out
            _isolators_12 = camshaft_contactor_set.on_off(["OS2"], ["OS1"], contactor_locations, null, null);
            _isolators_34 = camshaft_contactor_set.on_off(["OS4"], ["OS3"], contactor_locations, null, null);
        }

        // The controller wheel. position: 0 off, 1-28 series, 29-43 parallel.
        public void set_controller(int position)
        {
            _wanted = Math.Max(0, Math.Min(controller_positions - 1, position));
        }

        // The weakening lever, 0-6. It is mechanically locked off the two running notches,
        // and the shunts drop out the moment the wheel leaves one.
        public void set_field_weakening(int step)
        {
            _field_wanted = Math.Max(0, Math.Min(field_positions - 1, step));
        }

        // -1 reverse, 0 neutral, 1 forward. Thrown only with the wheel at 0, as on the real
        // locomotive, where the two handles are interlocked.
        public bool set_reverser(int direction)
        {
            if (_position != 0 || _wanted != 0)
                return false;
            _reverser_set.switch_contactors(direction > 0 ? 2 : direction < 0 ? 3 : 1);
            return true;
        }

        // True from the moment the contactors are made to fall open until the wheel is back
        // at 0. The line contactor SL1 picks up only as the wheel passes position 1 and holds
        // itself after that, so a locomotive whose contactors dropped out at position 20
        // stays dead at 20 however the fault clears.
        public bool dropped_out { get; private set; } = false;

        // Call every simulation tick. Without control voltage or air, or when the line
        // contactors are not permitted (see power_circuit), every contactor falls open at
        // once, whatever the wheel says.
        public void simulate(float delta_seconds, bool line_contactors_permitted = true)
        {
            bool live = _control_power.State && _control_air.State && line_contactors_permitted;
            if (!live && _position > 0)
                dropped_out = true;
            if (_wanted == 0 && _position == 0)
                dropped_out = false;            // the wheel has been to 0, whatever else is wrong
            if (!live || dropped_out)
            {
                while (_position > 0)
                    move_one(up: false);
                _waited = 0.0f;
                return;
            }
            _waited += delta_seconds;
            while (_waited >= step_time)
            {
                _waited -= step_time;
                if (_position != _wanted)
                    move_one(up: _wanted > _position);
                else
                {
                    bool running = _position == series_running || _position == parallel_running;
                    int  field   = running ? _field_wanted : 0;
                    if (_field != field)
                        _field_set.switch_contactors((_field += field > _field ? 1 : -1) + 1);
                    else
                    {
                        _waited = 0.0f;         // nothing to do: do not save time up
                        break;
                    }
                }
            }
        }

        // ALWAYS one position at a time, even when everything is dropping out. Two sets
        // share every main contactor, and a set does nothing when asked for the row it
        // applied last; a jump would leave one of them believing a row is still shown that
        // the other has since overwritten. So position 28 belongs to whichever set the
        // wheel reaches it from: coming up from 27 it is the series set's last row, coming
        // down from 29 it is the parallel set's first. Checked in build_contactors.py.
        private void move_one(bool up)
        {
            if (_field != 0)
                _field_set.switch_contactors((_field = 0) + 1);      // shunts out before the wheel moves
            int was = _position;
            _position += up ? 1 : -1;
            if (_position < series_running)
                _series_set.switch_contactors(_position + 1);
            else if (_position > series_running)
                _parallel_set.switch_contactors(_position - series_running + 1);
            else if (was < series_running)
                _series_set.switch_contactors(series_running + 1);
            else
                _parallel_set.switch_contactors(1);
        }

        public void cut_out_motors(bool pair_12, bool pair_34)
        {
            _isolators_12.switch_contactors(pair_12 ? 2 : 1);
            _isolators_34.switch_contactors(pair_34 ? 2 : 1);
        }
    }
}
